// Verifies every API path the frontend calls against the RUNNING backend.
//
// Why not read the router stack: Express 5 stores mount matchers as opaque
// closures, and most CRUD routes are generated by defineResource() — so neither
// grepping the source nor walking the stack reliably enumerates routes. Sending
// a request and reading the answer is the only result that cannot be wrong.
//
// A 404 does NOT mean the route is missing. Two different 404s exist:
//   * the router's fallback -> code NOT_FOUND, message "المسار غير موجود."
//   * a handler's own 404   -> its own message ("المنتج غير موجود.")
// Only the first means the path is not served. The second means the path IS
// served and the row was not found — which is exactly what happens when a test
// invents an id. This tool resolves a REAL id per resource so a handler-404
// cannot be mistaken for a missing route.
process.env.REDIS_URL = "";

const { dbAdmin } = await import("./dist/config/database.js");
const { signAccessToken } = await import("./dist/utils/jwt.js");
const app = (await import("./dist/app.js")).default;

const c = await dbAdmin.company.findFirstOrThrow({ where: { deletedAt: null }, select: { id: true, ownerId: true } });
const u = await dbAdmin.user.findUniqueOrThrow({
  where: { id: c.ownerId },
  select: { id: true, email: true, securityStamp: true, companyId: true, isPlatformAdmin: true },
});
const { token } = signAccessToken({
  sub: u.id, sid: "00000000-0000-4000-8000-000000000000", email: u.email,
  securityStamp: u.securityStamp ?? "", companyId: u.companyId, isPlatformAdmin: u.isPlatformAdmin,
});

// A real id per resource, so handler lookups succeed and the route proves itself.
const nd = { deletedAt: null };
const one = async (model, where = nd) => (await dbAdmin[model].findFirst({ where, select: { id: true } }))?.id;
const ids = {
  products: await one("product"),
  orders: await one("order"),
  coupons: await one("coupon"),
  batches: await one("productionBatch"),
  fulfillment: await one("fulfillmentBatch", {}),
  returns: await one("shippingReturn", {}),
  stores: await one("store", {}),
  customers: await one("customer"),
  vendors: await one("vendor"),
  companies: await one("company"),
  operations: await one("stockOperation"),
  counts: await one("stockCount"),
};

/** Picks the most fitting real id for a path, so handler lookups can succeed. */
function idFor(raw) {
  const table = [
    [/^\/sales\/orders/, ids.orders],
    [/^\/sales\/coupons/, ids.coupons],
    [/^\/sales\/customers/, ids.customers],
    [/^\/sales\/fulfillment-batches/, ids.fulfillment],
    [/^\/sales\/shipping-returns/, ids.returns],
    [/^\/production\/batches/, ids.batches],
    [/^\/purchasing\/vendors/, ids.vendors],
    [/^\/platform\/companies/, ids.companies],
    [/^\/system\/stores/, ids.stores],
    [/^\/catalog\/products/, ids.products],
    [/^\/inventory\/operations/, ids.operations],
    [/^\/inventory\/counts/, ids.counts],
  ];
  for (const [re, id] of table) if (re.test(raw) && id) return id;
  return ids.products ?? ids.orders ?? "00000000-0000-4000-8000-000000000000";
}

const server = app.listen(0);
await new Promise((r) => server.once("listening", r));
const BASE = `http://127.0.0.1:${server.address().port}`;

const PATHS = process.argv.slice(2);
if (PATHS.length === 0) {
  console.log("usage: node verify-contract.mjs /path/one /path/two ...");
  server.close();
  process.exit(1);
}

/**
 * Tries each verb, because a route's existence is per-method.
 *
 * A GET to a POST-only path returns the router fallback 404, which would read
 * as "missing" even though the path is served. So a path counts as present if
 * ANY verb reaches a handler; only when every verb falls through to the router
 * fallback is it genuinely absent.
 */
const VERBS = ["GET", "POST", "PATCH", "PUT", "DELETE"];

const results = [];
for (const raw of PATHS) {
  const path = "/api/v1" + raw.replace(/:x/g, idFor(raw));

  let best = null; // the most informative result across verbs
  for (const method of VERBS) {
    let status = 0;
    let body = null;
    try {
      const res = await fetch(BASE + path, {
        method,
        headers: {
          Authorization: "Bearer " + token,
          ...(method === "POST" || method === "PATCH" || method === "PUT" ? { "Content-Type": "application/json" } : {}),
        },
        ...(method === "POST" || method === "PATCH" || method === "PUT" ? { body: "{}" } : {}),
        signal: AbortSignal.timeout(20000),
      });
      status = res.status;
      body = await res.json().catch(() => null);
    } catch {
      status = -1;
    }

    const routerFallback = status === 404 && body?.code === "NOT_FOUND" && /المسار/.test(body?.message ?? "");
    // A handler answered: the route exists for this verb.
    if (!routerFallback && status !== -1) {
      best = { method, status };
      break;
    }
    if (status === -1) best = best ?? { method, status: -1 };
  }

  const verdict = best === null ? "MISSING" : best.status === -1 ? "ERROR" : "exists";
  results.push([verdict, raw, best?.status ?? 404, best?.method ?? "-"]);
}

for (const [verdict, raw, status, method] of results) {
  if (verdict === "MISSING" || verdict === "ERROR") console.log(`${verdict.padEnd(8)} ${raw}  (${status})`);
}
const missing = results.filter((r) => r[0] === "MISSING").length;
const errored = results.filter((r) => r[0] === "ERROR").length;
console.log(`\nchecked ${results.length} paths — missing ${missing}, errored ${errored}, ok ${results.length - missing - errored}`);

server.close();
process.exit(0);
